"""Comparison with RISE reference results (commit 1b2edfa), generated by validation/matlab."""
import os
from pathlib import Path

import numpy as np
import pytest
import scipy.io as sio

from msdsge.solve import SolveError, solve_first_order
from test_solve import fwz

REF = Path(__file__).parents[1] / "validation" / "ref"


def _dense(x):
    return np.asarray(x.todense() if hasattr(x, "todense") else x, float)


@pytest.mark.parametrize("k", [1, 2, 3])
@pytest.mark.parametrize("solver", ["mnk", "mfi"])
def test_fwz_matches_rise(k, solver):
    ref = sio.loadmat(REF / "fwz.mat", squeeze_me=True, struct_as_record=False)[f"p{k}_{solver}"]
    m, p = fwz(k)
    if ref.retcode != 0:  # RISE fails too (mfi in parameterisation 1)
        with pytest.raises(SolveError):
            solve_first_order(m, p, solver=solver)
        return
    s = solve_first_order(m, p, solver=solver)
    iP, iR = m.endogenous.index("PAI"), m.endogenous.index("R")
    for r in range(2):
        Tz = _dense(ref.Tz[r])  # rows [PAI, R]; columns [R(-1), PAI(-1), sigma, E]
        mine = np.column_stack([s.T[r][[iP, iR]][:, [iR, iP]], np.zeros(2), s.R[r][[iP, iR], 0]])
        assert mine == pytest.approx(Tz, abs=1e-8 if solver == "mnk" else 1e-6)  # tolerance of RISE's mfi
    assert s.Q == pytest.approx(_dense(ref.Q))
    assert s.is_stable == bool(ref.stable)


def test_filter_matches_rise():
    """Likelihood and regime probabilities equal to RISE's (kf_riccati_tol=0 in the switching case)."""
    import pandas as pd
    from msdsge import Model
    from test_filter import AR, MS
    ref = sio.loadmat(REF / "filter.mat", squeeze_me=True, struct_as_record=False)
    x = pd.read_csv(REF / "filter_ar_data.csv")
    r = Model.from_text(AR).solve().filter(x)
    assert r.loglik_t == pytest.approx(np.ravel(ref["ar"].Incr), abs=1e-12)
    x = pd.read_csv(REF / "filter_ms_data.csv")
    r = Model.from_text(MS).solve().filter(x)
    tol0 = sio.loadmat(REF / "filter_ms_tol0.mat", squeeze_me=True, struct_as_record=False)["tol0"]
    assert r.loglik_t == pytest.approx(np.ravel(tol0.Incr), abs=1e-11)
    assert r.loglik == pytest.approx(float(tol0.LogLik), abs=1e-9)
    # with RISE's default Riccati shortcut (1e-6) the difference is small, but not zero
    assert r.loglik == pytest.approx(float(ref["ms"].LogLik), abs=0.05)
    # probabilities: compared with RISE's default run, hence the tolerance
    assert r.filtered_probs["regime_1"].to_numpy() == pytest.approx(ref["ms"].updated_regime_probabilities__regime_1, abs=0.02)
    assert r.smoothed_probs["regime_1"].to_numpy() == pytest.approx(ref["ms"].smoothed_regime_probabilities__regime_1, abs=0.02)


@pytest.mark.parametrize("case", ["A", "B"])
def test_regime_specific_steady_state_and_endogenous_probabilities(case):
    """A: regime-specific steady state. B: endogenous probabilities. Solution, filter and smoothing."""
    import pandas as pd
    from msdsge import load
    ex = Path(__file__).parents[1] / "examples"
    ref = sio.loadmat(REF / "refAB.mat", squeeze_me=True, struct_as_record=False)[case]
    s = load(ex / f"ref{case}.mod").solve()
    assert s.endogenous_switching == (case == "B")
    for r in range(2):
        Tz = np.asarray(ref.Tz[r], float)      # rows [X, Z]; columns [X(-1), Z(-1), sigma, E]
        assert np.column_stack([s.T[r], np.zeros(2), s.R[r]]) == pytest.approx(Tz, abs=1e-6)
        assert s.ss[r] == pytest.approx(np.ravel(ref.ss[r]).astype(float), abs=1e-9)
    assert s.Q == pytest.approx(ref.Q, abs=1e-12)
    f = s.filter(pd.read_csv(REF / f"ref{case}_data.csv"))
    assert f.loglik_t == pytest.approx(np.ravel(ref.Incr), abs=1e-7)
    assert f.filtered_probs["regime_1"].to_numpy() == pytest.approx(ref.upd1, abs=1e-7)
    assert f.smoothed_probs["regime_1"].to_numpy() == pytest.approx(ref.smo1, abs=1e-5)
    assert f.filtered_states["Z"].to_numpy() == pytest.approx(ref.updZ, abs=1e-6)
    # IRF per regime: RISE returns 11 rows, the first being the period before the shock
    irf = s.irf(periods=10, size=1.0)
    for r in range(2):
        assert irf.loc[("E", r + 1), "Z"].to_numpy() == pytest.approx(ref.irfZ[1:, r], abs=1e-6)


def test_unique_steady_state_frwz_rbc():
    """RBC of Foerster et al. (2016): the steady state of regime 2 does not exist; single point.

    Steady state (the one printed in Maih, 2015, §6.4), T and R equal to RISE's. The uncertainty
    constant of the forward-looking variables differs by up to 0.01 (open issue recorded in docs/VALIDATION.md).
    """
    import warnings
    from msdsge import Model, SteadyStateError
    from msdsge.convert import rs_to_mod
    rs = Path(os.environ.get("RISE_TOOLBOX", Path.home() / "RISE_toolbox")) / "examples/MarkovSwitching/FoersterRubioRamirezWaggonerZha/QE2016/rbcs.rs"
    if not rs.exists():
        pytest.skip("RISE not installed")
    ref = sio.loadmat(REF / "unique.mat", squeeze_me=True, struct_as_record=False)
    m = Model.from_text(rs_to_mod(rs))
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        with pytest.raises(SteadyStateError, match="unique"):
            m.solve()
        s = m.solve(steady_state="unique")
    order = [m.endogenous.index(v) for v in ("C", "K", "Z")]     # row order in RISE
    for r in range(2):
        Tz = np.asarray(ref["Tz"][r], float)                     # columns [K(-1), Z(-1), sigma, E]
        assert s.ss[r][order] == pytest.approx(np.ravel(ref["ss"][r]), abs=1e-6)
        assert s.ss[r][order] == pytest.approx([2.082588, 22.150375, 1.007058], abs=1e-6)
        mine = s.T[r][order][:, [m.endogenous.index("K"), m.endogenous.index("Z")]]
        assert mine == pytest.approx(Tz[:, :2], abs=1e-6)
        assert s.R[r][order, 0] == pytest.approx(Tz[:, 3], abs=1e-6)
        assert s.c[r][order] == pytest.approx(Tz[:, 2], abs=0.011)
        assert s.c[r][m.endogenous.index("Z")] == pytest.approx(Tz[2, 2], abs=1e-6)


def test_smoothed_states_and_shocks_match_rise():
    """Latent state with regime switching: smoothed states and shocks (kf_riccati_tol=0 in RISE)."""
    import pandas as pd
    from msdsge import Model, load
    from test_filter import MS
    ref = sio.loadmat(REF / "smooth_ms.mat", squeeze_me=True, struct_as_record=False)
    f = Model.from_text(MS).solve().filter(pd.read_csv(REF / "filter_ms_data.csv"))
    assert f.smoothed_states["z"].to_numpy() == pytest.approx(ref["smo_z"], abs=1e-10)
    assert f.smoothed_shocks["e"].to_numpy() == pytest.approx(ref["smo_e"], abs=1e-10)
    assert f.smoothed_shocks["u"].to_numpy() == pytest.approx(ref["smo_u"], abs=1e-10)
    ex = Path(__file__).parents[1] / "examples"
    for case in "AB":
        r = sio.loadmat(REF / "refAB.mat", squeeze_me=True, struct_as_record=False)[case]
        f = load(ex / f"ref{case}.mod").solve().filter(pd.read_csv(REF / f"ref{case}_data.csv"))
        assert f.smoothed_states["Z"].to_numpy() == pytest.approx(r.smoZ, abs=1e-6)
        assert f.smoothed_shocks["E"].to_numpy() == pytest.approx(r.smoE, abs=1e-6)


def test_posterior_kernel_matches_rise():
    """Posterior with quantile priors (beta, inverse gamma, normal, gamma) against log_posterior_kernel."""
    import warnings
    import pandas as pd
    from msdsge import Model
    from msdsge.convert import rs_to_mod
    from msdsge.estimation import EstimationProblem
    ref = sio.loadmat(REF / "post2.mat", squeeze_me=True, struct_as_record=False)
    m = Model.from_text(rs_to_mod(Path(__file__).parents[1] / "validation" / "matlab" / "est_ms2.rs"))
    pr = EstimationProblem(m, pd.read_csv(REF / "filter_ms_data.csv"))
    assert pr.names == list(ref["names"])
    assert [p.mean for p in pr.priors] == pytest.approx(ref["prior_mean"], abs=1e-5)
    assert [p.std for p in pr.priors] == pytest.approx(ref["prior_stdev"], abs=1e-5)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        for pt, (post, lik, prior) in zip(ref["pts"], ref["res"]):
            assert pr.loglik(pt) == pytest.approx(lik, abs=1e-6)
            assert pr.logprior(pt) == pytest.approx(prior, abs=1e-5)
            assert pr.logpost(pt) == pytest.approx(post, abs=1e-5)
